async (page) => {
  const B='http://localhost:3000';
  const email=`probe-w-${Date.now()}@example.test`, password='Passw0rd!probe';
  await page.request.post(B+'/api/Users',{data:{email,password,passwordRepeat:password}});
  const a = (await (await page.request.post(B+'/rest/user/login',{data:{email,password}})).json()).authentication;
  const h={Authorization:'Bearer '+a.token};
  await page.request.post(B+'/api/Addresss',{headers:h,data:{country:'Ukraine',fullName:'Test Customer',mobileNum:501234567,zipCode:'01001',streetAddress:'1 Khreshchatyk Street',city:'Kyiv',state:'Kyiv'}});
  const card = (await (await page.request.post(B+'/api/Cards',{headers:h,data:{fullName:'Test Customer',cardNum:4111111111111111,expMonth:12,expYear:2090}})).json()).data;
  await page.request.post(B+'/api/BasketItems',{headers:h,data:{ProductId:3,BasketId:String(a.bid),quantity:1}});
  const w1 = await page.request.put(B+'/rest/wallet/balance',{headers:h,data:{balance:5,paymentId:card.id}});
  const out = {w1:[w1.status(), await w1.text()]};
  await page.context().clearCookies();
  await page.context().addCookies([{name:'cookieconsent_status',value:'dismiss',domain:'localhost',path:'/'},{name:'language',value:'en',domain:'localhost',path:'/'},{name:'token',value:a.token,domain:'localhost',path:'/'}]);
  await page.goto(B+'/'); 
  await page.evaluate(([t,b])=>{localStorage.setItem('token',t);sessionStorage.setItem('bid',String(b));},[a.token,a.bid]);
  await page.goto(B+'/#/order-history'); await page.reload(); await page.waitForTimeout(1500);
  out.emptyHist = await page.locator('app-order-history').ariaSnapshot();
  await page.goto(B+'/#/basket'); await page.getByText('Eggfruit').first().waitFor();
  await page.locator('#checkoutButton').click();
  await page.getByRole('row', {name:/Test Customer/}).getByRole('radio').click();
  await page.getByRole('button',{name:'Proceed to payment selection'}).click();
  await page.getByRole('row',{name:/Standard Delivery/}).getByRole('radio').click();
  await page.getByRole('button',{name:'Proceed to delivery method selection'}).click();
  await page.waitForURL(/payment/); await page.waitForTimeout(1500);
  out.payWallet = await page.locator('app-payment').ariaSnapshot().then(s=>s.split('\n').filter(l=>/wallet|Pay|Balance/i.test(l)).join('\n'));
  out.payBtnHtml = await page.getByRole('button',{name:/^Pay /}).evaluate(e=>e.outerHTML.replace(/<svg.*?<\/svg>/gs,'').slice(0,600));
  const w2 = await page.request.put(B+'/rest/wallet/balance',{headers:h,data:{balance:3.99,paymentId:card.id}});
  out.w2=[w2.status(), await w2.text()];
  await page.reload(); await page.waitForTimeout(1500);
  out.url=page.url();
  out.payWallet2 = await page.locator('app-payment').ariaSnapshot().then(s=>s.split('\n').filter(l=>/wallet|Pay|Balance/i.test(l)).join('\n'));
  await page.getByRole('button',{name:/^Pay /}).click();
  await page.waitForURL(/order-summary/); await page.waitForTimeout(1500);
  out.sum = await page.locator('app-order-summary').ariaSnapshot();
  return JSON.stringify(out,null,1);
}

