const MS_IN_SECOND = 1000;
const SECONDS_IN_MINUTE = 60;

const MONTH_CODES = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'] as const;

export class DateHelper {
  static secondsToMs(seconds: number): number {
    return seconds * MS_IN_SECOND;
  }

  static minutesToMs(minutes: number): number {
    return DateHelper.secondsToMs(minutes * SECONDS_IN_MINUTE);
  }

  /** `OCT26` for October 2026, in the local time of the machine. */
  static toMonthYearCode(date: Date): string {
    const year = String(date.getFullYear()).slice(-2);
    return `${MONTH_CODES[date.getMonth()]}${year}`;
  }

  /** The first day of the previous month, in the local time of the machine. */
  static previousMonth(date: Date): Date {
    return new Date(date.getFullYear(), date.getMonth() - 1, 1);
  }
}

