import { encode } from 'z85';
import { DateHelper } from '@/utils/helpers/date-helper';

/**
 * Coupon codes as `test-cases/README.md` defines them: Z85 of `<MMM><YY>-<NN>`.
 * The server accepts a coupon only in the month that it names, so the code is built at run time.
 */
export class CouponHelper {
  static forMonth(date: Date, discountPercent: number): string {
    const text = `${DateHelper.toMonthYearCode(date)}-${String(discountPercent).padStart(2, '0')}`;
    const code = encode(text);
    if (!code) {
      throw new Error(`Cannot Z85-encode the coupon text "${text}"`);
    }
    return code;
  }

  static currentMonth(discountPercent: number): string {
    return CouponHelper.forMonth(new Date(), discountPercent);
  }

  static previousMonth(discountPercent: number): string {
    return CouponHelper.forMonth(DateHelper.previousMonth(new Date()), discountPercent);
  }
}

