import type { BasketLine, DeliveryMethod, OrderTotals } from '@/utils/types/shop';

const CENTS_IN_UNIT = 100;
const PERCENT_BASE = 100;
const BONUS_DIVISOR = 10;
const PRICE_DECIMALS = 2;

/**
 * The expected money values of a basket and an order, calculated from the test data.
 * The shop shows prices with two decimals and the sign `¤`.
 */
export class PriceHelper {
  static format(amount: number): string {
    return `${amount.toFixed(PRICE_DECIMALS)}¤`;
  }

  /** The wallet balance shows two decimals and no sign. */
  static formatBalance(amount: number): string {
    return amount.toFixed(PRICE_DECIMALS);
  }

  static roundToCents(amount: number): number {
    return Math.round(amount * CENTS_IN_UNIT) / CENTS_IN_UNIT;
  }

  static basketTotal(lines: BasketLine[]): number {
    return PriceHelper.roundToCents(lines.reduce((sum, line) => sum + line.product.price * line.quantity, 0));
  }

  static itemCount(lines: BasketLine[]): number {
    return lines.reduce((sum, line) => sum + line.quantity, 0);
  }

  static orderTotals(lines: BasketLine[], delivery: DeliveryMethod, discountPercent: number): OrderTotals {
    const items = PriceHelper.basketTotal(lines);
    const promotion = PriceHelper.roundToCents((items * discountPercent) / PERCENT_BASE);
    const total = PriceHelper.roundToCents(items + delivery.price - promotion);
    return { items, delivery: delivery.price, promotion, total };
  }

  /** Bonus points of one product: price / 10, rounded to a whole number, × quantity. */
  static bonusPoints(lines: BasketLine[]): number {
    return lines.reduce((sum, line) => sum + Math.round(line.product.price / BONUS_DIVISOR) * line.quantity, 0);
  }
}

