import { BaseApiClient } from '@/core/api/base-api-client';
import { API_ROUTES } from '@/utils/constants/routes';

interface LoginResponse {
  authentication: { token: string; bid: number; umail: string };
}

export interface LoginSession {
  token: string;
  basketId: number;
}

export class UserApiClient extends BaseApiClient {
  async register(email: string, password: string): Promise<void> {
    const response = await this.request.post(API_ROUTES.users, {
      data: { email, password, passwordRepeat: password },
    });
    await this.readJson(response, `Register the customer ${email}`);
  }

  async login(email: string, password: string): Promise<LoginSession> {
    const response = await this.request.post(API_ROUTES.login, { data: { email, password } });
    const body = await this.readJson<LoginResponse>(response, `Log in the customer ${email}`);
    return { token: body.authentication.token, basketId: body.authentication.bid };
  }
}

