import { API_ROUTES } from '@/utils/constants/routes';
import type { Customer, SavedAddress, SavedCard } from '@/utils/types/shop';

interface CreatedRecord {
  data: { id: number };
}

/** Saved addresses, saved cards and the wallet of a customer. */
export class PaymentApiClient extends BaseApiClient {
  async addAddress(customer: Customer, address: SavedAddress): Promise<number> {
    const response = await this.request.post(API_ROUTES.addresses, {
      headers: this.authHeaders(customer.token),
      data: address,
    });
    return (await this.readJson<CreatedRecord>(response, 'Save the address')).data.id;
  }

  async addCard(customer: Customer, card: SavedCard): Promise<number> {
    const response = await this.request.post(API_ROUTES.cards, {
      headers: this.authHeaders(customer.token),
      data: card,
    });
    return (await this.readJson<CreatedRecord>(response, 'Save the card')).data.id;
  }

  /** Adds money to the wallet. The server needs a saved card of the customer. */
  async topUpWallet(customer: Customer, amount: number, cardId: number): Promise<void> {
    const response = await this.request.put(API_ROUTES.walletBalance, {
      headers: this.authHeaders(customer.token),
      data: { balance: amount, paymentId: cardId },
    });
    await this.readJson(response, `Add ${amount} to the wallet`);
  }
}

