import type { Locator, Page } from '@playwright/test';
import { expectHidden, expectVisible } from '@/utils/assertions/ui-assertions';

/** The menu of the button `Account` in the top bar, with the sub-menu `Orders & Payment`. */
export class AccountMenuComponent {
  private readonly menuItems: Locator;

  constructor(private readonly page: Page) {
    this.menuItems = page.locator('.cdk-overlay-container').getByRole('menuitem');
  }

  private item(text: string): Locator {
    return this.menuItems.filter({ hasText: text });
  }

  async shouldSeeLoginItem(): Promise<void> {
    await expectVisible(this.item('Login'), 'Account menu item `Login`');
  }

  async shouldSeeLogoutItem(): Promise<void> {
    await expectVisible(this.item('Logout'), 'Account menu item `Logout`');
  }

  async shouldSeeEmail(email: string): Promise<void> {
    await expectVisible(this.item(email), `Account menu item with the email ${email}`);
  }

  async shouldNotSeeEmail(email: string): Promise<void> {
    await expectHidden(this.item(email), `Account menu item with the email ${email}`);
  }

  async close(): Promise<void> {
    await this.page.keyboard.press('Escape');
    await expectHidden(this.menuItems, 'Account menu');
  }

  async clickOrderHistory(): Promise<void> {
    await this.item('Orders & Payment').click();
    await this.item('Order History').click();
  }

  async clickDigitalWallet(): Promise<void> {
    await this.item('Orders & Payment').click();
    await this.item('Digital Wallet').click();
  }
}

