import type { Locator, Page } from '@playwright/test';
import { expectContainText, expectStaysHidden, expectVisible } from '@/utils/assertions/ui-assertions';
import { DateHelper } from '@/utils/helpers/date-helper';

const NO_MESSAGE_HOLD_SECONDS = 2;

/** The pop-up messages at the bottom of the page: confirmations and errors. */
export class SnackBarComponent {
  private readonly confirmation: Locator;
  private readonly error: Locator;

  constructor(page: Page) {
    this.confirmation = page.locator('.mat-mdc-snack-bar-container.confirmBar');
    this.error = page.locator('.mat-mdc-snack-bar-container.errorBar');
  }

  async shouldSeeConfirmation(text: string): Promise<void> {
    const message = this.confirmation.filter({ hasText: text });
    await expectVisible(message, 'Confirmation message');
    await expectContainText(message, text, 'Confirmation message');
  }

  async shouldSeeError(text: string): Promise<void> {
    const message = this.error.filter({ hasText: text });
    await expectVisible(message, 'Error message');
    await expectContainText(message, text, 'Error message');
  }

  async shouldNotSeeError(): Promise<void> {
    await expectStaysHidden(this.error, DateHelper.secondsToMs(NO_MESSAGE_HOLD_SECONDS), 'Error message');
  }
}

