import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { UI_ROUTES } from '@/utils/constants/routes';
import type { Customer } from '@/utils/types/shop';

export class LoginPage extends BasePage {
  private readonly title: Locator;
  private readonly emailField: Locator;
  private readonly passwordField: Locator;
  private readonly loginButton: Locator;
  private readonly errorMessage: Locator;

  constructor(page: Page) {
    super(page);
    const form = page.locator('app-login');
    this.title = form.getByRole('heading', { name: 'Login', level: 1 });
    this.emailField = form.locator('#email');
    this.passwordField = form.locator('#password');
    this.loginButton = form.locator('#loginButton');
    this.errorMessage = form.locator('.error');
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.login);
  }

  async shouldSeePage(): Promise<void> {
    await expectVisible(this.title, 'Login page title');
  }

  async shouldSeeLoginForm(): Promise<void> {
    await expectText(this.title, 'Login', 'Login page title');
    await expectVisible(this.emailField, 'Field `Email`');
    await expectVisible(this.passwordField, 'Field `Password`');
    await expectVisible(this.loginButton, 'Button `Log in`');
    await expectText(this.loginButton, /Log in/, 'Button `Log in`');
  }

  /** A real UI login. Use it only when the login screen itself is under test. */
  async login(email: string, password: string): Promise<void> {
    await this.emailField.fill(email);
    await this.passwordField.fill(password);
    await this.loginButton.click();
  }

  async shouldSeeInvalidCredentialsError(): Promise<void> {
    await expectText(this.errorMessage, UI_MESSAGES.invalidLogin, 'Login error message');
  }

  async shouldStayOnLoginPage(): Promise<void> {
    await expectUrl(this.page, /#\/login$/, 'Login page');
    await this.shouldSeePage();
  }

  /**
   * Puts the API session of the customer into the browser before the app loads:
   * `token` in localStorage and in a cookie, `bid` (the basket id) in sessionStorage.
   */
  async authenticate(customer: Customer): Promise<void> {
    const appUrl = new URL(this.page.url() === 'about:blank' ? UI_ROUTES.home : this.page.url(), this.baseUrl());
    await this.page.context().addCookies([
      { name: 'token', value: customer.token, domain: appUrl.hostname, path: '/' },
    ]);
    await this.page.addInitScript(
      ({ token, basketId }) => {
        window.localStorage.setItem('token', token);
        window.sessionStorage.setItem('bid', String(basketId));
      },
      { token: customer.token, basketId: customer.basketId },
    );
    await this.page.goto(UI_ROUTES.search, { waitUntil: 'domcontentloaded' });
    await this.navbar.shouldSeeBasketCountLoaded();
  }

  private baseUrl(): string {
    return process.env.BASE_URL ?? 'http://localhost:3000';
  }
}

