import type { Locator, Page } from '@playwright/test';
import { expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { Product } from '@/utils/types/shop';

/** One product card on the product list `/#/search`. */
export class ProductCardComponent {
  private readonly card: Locator;

  constructor(page: Page, private readonly product: Product) {
    this.card = page.locator('app-product').filter({
      has: page.locator('.item-name', { hasText: product.name }),
    });
  }

  private get addToBasketButton(): Locator {
    return this.card.getByRole('button', { name: 'Add to Basket' });
  }

  async shouldSeeNamePriceAndButton(): Promise<void> {
    await expectText(this.card.locator('.item-name'), this.product.name, 'Product name on the card');
    await expectText(this.card.locator('.item-price'), PriceHelper.format(this.product.price), `Price of ${this.product.name}`);
    await expectVisible(this.addToBasketButton, `Button \`Add to Basket\` of ${this.product.name}`);
  }

  async clickAddToBasket(): Promise<void> {
    await this.addToBasketButton.click();
  }
}

