import type { Locator, Page } from '@playwright/test';
import { expectCount, expectHidden, expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine, Product } from '@/utils/types/shop';

/** The product table `app-purchase-basket`. The basket page and the order summary show it. */
export class BasketLinesComponent {
  private readonly rows: Locator;

  constructor(page: Page) {
    this.rows = page.locator('app-purchase-basket mat-row');
  }

  row(product: Product): Locator {
    return this.rows.filter({
      has: this.rows.page().locator('mat-cell.mat-column-product').getByText(product.name, { exact: true }),
    });
  }

  quantityButtons(product: Product): Locator {
    return this.row(product).locator('mat-cell.mat-column-quantity').getByRole('button');
  }

  removeButton(product: Product): Locator {
    return this.row(product).locator('mat-cell.mat-column-remove').getByRole('button');
  }

  async shouldSeeLines(lines: BasketLine[]): Promise<void> {
    await expectCount(this.rows, lines.length, 'Basket rows');
    for (const line of lines) {
      await this.shouldSeeLine(line);
    }
  }

  async shouldSeeLine(line: BasketLine): Promise<void> {
    const row = this.row(line.product);
    await expectVisible(row, `Basket row of ${line.product.name}`);
    await this.shouldSeeQuantity(line.product, line.quantity);
    await expectText(
      row.locator('mat-cell.mat-column-price'),
      PriceHelper.format(line.product.price),
      `Price of ${line.product.name}`,
    );
  }

  async shouldSeeQuantity(product: Product, quantity: number): Promise<void> {
    await expectText(
      this.row(product).locator('mat-cell.mat-column-quantity'),
      String(quantity),
      `Quantity of ${product.name}`,
    );
  }

  async shouldNotSeeProduct(product: Product): Promise<void> {
    await expectHidden(this.row(product), `Basket row of ${product.name}`);
  }

  async shouldSeeNoProducts(): Promise<void> {
    await expectCount(this.rows, 0, 'Basket rows');
  }
}

