import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import type { SavedAddress } from '@/utils/types/shop';

/** The checkout step `Select an address`. */
export class AddressSelectPage extends BasePage {
  private readonly title: Locator;
  private readonly continueButton: Locator;

  constructor(page: Page) {
    super(page);
    this.title = page.getByRole('heading', { name: 'Select an address', level: 1 });
    this.continueButton = page.getByRole('button', { name: 'Proceed to payment selection' });
  }

  private addressRow(address: SavedAddress): Locator {
    return this.page.locator('app-address mat-row').filter({ hasText: address.streetAddress });
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, /#\/address\/select$/, 'Address step');
    await expectVisible(this.title, 'Title `Select an address`');
  }

  async shouldSeeSavedAddress(address: SavedAddress): Promise<void> {
    const row = this.addressRow(address);
    await expectVisible(row, 'Saved address row');
