import type { Locator, Page } from '@playwright/test';
import { expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import { CARD_VISIBLE_DIGITS } from '@/utils/constants/customer-data';
import type { SavedCard } from '@/utils/types/shop';

/** The list of saved cards on the page `My Payment Options`. */
export class SavedCardsComponent {
  constructor(private readonly page: Page) {}

  private cardRow(card: SavedCard): Locator {
    const lastDigits = String(card.cardNum).slice(-CARD_VISIBLE_DIGITS);
    return this.page.locator('app-payment-method mat-row').filter({ hasText: lastDigits });
  }

  async shouldSeeCard(card: SavedCard): Promise<void> {
    const row = this.cardRow(card);
    const lastDigits = String(card.cardNum).slice(-CARD_VISIBLE_DIGITS);
    await expectVisible(row, 'Saved card row');
    await expectText(row.locator('mat-cell').nth(1), new RegExp(`\\*+${lastDigits}$`), 'Saved card number');
    await expectText(row.locator('mat-cell').nth(2), card.fullName, 'Saved card holder');
    await expectText(row.locator('mat-cell').nth(3), `${card.expMonth}/${card.expYear}`, 'Saved card expiry');
  }

  async selectCard(card: SavedCard): Promise<void> {
    await this.cardRow(card).getByRole('radio').check();
  }
}

