import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { BasketLinesComponent } from '@/page-objects/components/basket-lines.component';
import { expectContainText, expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { CARD_VISIBLE_DIGITS } from '@/utils/constants/customer-data';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine, OrderTotals, SavedAddress, SavedCard } from '@/utils/types/shop';

/** The checkout step `Order Summary`, before the order is placed. */
export class OrderSummaryPage extends BasePage {
  private readonly lines: BasketLinesComponent;
  private readonly summary: Locator;
  private readonly addressAndPayment: Locator;
  private readonly placeOrderButton: Locator;

  constructor(page: Page) {
    super(page);
    this.lines = new BasketLinesComponent(page);
    this.summary = page.locator('app-order-summary');
    this.addressAndPayment = this.summary.locator('mat-card').first();
    this.placeOrderButton = page.getByRole('button', { name: 'Complete your purchase' });
  }

  private totalsValue(label: string): Locator {
    return this.summary.locator('tr').filter({ has: this.page.locator('td.label', { hasText: label }) }).locator('td.price');
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, /#\/order-summary$/, 'Order summary step');
    await expectVisible(this.summary.getByText('Order Summary', { exact: true }), 'Title `Order Summary`');
  }

  async shouldSeeLines(lines: BasketLine[]): Promise<void> {
    await this.lines.shouldSeeLines(lines);
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    await expectText(this.totalsValue('Items'), PriceHelper.format(totals.items), 'Order summary: items');
    await expectText(this.totalsValue('Delivery'), PriceHelper.format(totals.delivery), 'Order summary: delivery');
    await expectText(this.totalsValue('Promotion'), PriceHelper.format(totals.promotion), 'Order summary: promotion');
    await expectText(this.totalsValue('Total Price'), PriceHelper.format(totals.total), 'Order summary: total price');
  }

  async shouldSeeAddress(address: SavedAddress): Promise<void> {
    await expectContainText(this.addressAndPayment, address.fullName, 'Order summary: address name');
    await expectContainText(
      this.addressAndPayment,
      `${address.streetAddress}, ${address.city}, ${address.state}, ${address.zipCode}`,
      'Order summary: address',
    );
    await expectContainText(this.addressAndPayment, address.country, 'Order summary: address country');
  }

  async shouldSeeCardPayment(card: SavedCard): Promise<void> {
    const lastDigits = String(card.cardNum).slice(-CARD_VISIBLE_DIGITS);
    await expectContainText(this.addressAndPayment, UI_MESSAGES.cardPaymentMethod(lastDigits), 'Order summary: card');
    await expectContainText(this.addressAndPayment, card.fullName, 'Order summary: card holder');
  }

  async shouldSeeWalletPayment(): Promise<void> {
    await expectContainText(
      this.addressAndPayment,
      `Payment Method ${UI_MESSAGES.walletPaymentMethod}`,
      'Order summary: payment method',
    );
  }

  async clickPlaceOrder(): Promise<void> {
    await this.placeOrderButton.click();
  }
}

