import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectCount, expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine, OrderTotals } from '@/utils/types/shop';

const ORDER_COMPLETION_URL = /#\/order-completion\/([\w-]+)$/;

/** The confirmation page `/#/order-completion/<order ID>`. It shows the totals that the server saved. */
export class OrderCompletionPage extends BasePage {
  private readonly title: Locator;
  private readonly productRows: Locator;
  private readonly totalsValues: Locator;

  constructor(page: Page) {
    super(page);
    const root = page.locator('app-order-completion');
    this.title = root.getByRole('heading', { level: 1 });
    this.productRows = root.locator('mat-row');
    this.totalsValues = root.locator('mat-footer-cell.mat-column-total-price td');
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, ORDER_COMPLETION_URL, 'Order confirmation page');
    await expectVisible(this.title, 'Order confirmation title');
  }

  async shouldSeeOrderAccepted(): Promise<void> {
    await this.shouldSeePage();
    await expectText(this.title, UI_MESSAGES.orderPlaced, 'Order confirmation message');
  }

  readOrderId(): string {
    const match = ORDER_COMPLETION_URL.exec(this.page.url());
    if (!match) {
      throw new Error(`The URL ${this.page.url()} is not an order confirmation URL`);
    }
    return match[1];
  }

  async shouldSeeLines(lines: BasketLine[]): Promise<void> {
    await expectCount(this.productRows, lines.length, 'Order confirmation product rows');
    for (const line of lines) {
      const row = this.productRows.filter({
        has: this.page.locator('mat-cell.mat-column-product').getByText(line.product.name, { exact: true }),
      });
      await expectText(row.locator('mat-cell.mat-column-quantity'), String(line.quantity), `Quantity of ${line.product.name}`);
      await expectText(
        row.locator('mat-cell.mat-column-price'),
        PriceHelper.format(line.product.price),
        `Price of ${line.product.name}`,
      );
    }
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    const expected = [totals.items, totals.delivery, totals.promotion, totals.total].map(PriceHelper.format);
    await expectText(this.totalsValues, expected, 'Order confirmation: items, delivery, promotion, total price');
  }
}

