/** Cookies that hide the cookie banner and the language message (`juice-shop-app.md`, sections 2 and 3). */
const APP_COOKIES = [
  { name: 'cookieconsent_status', value: 'dismiss' },
  { name: 'language', value: 'en' },
];

export const test = base.extend<PageFixtures>({
  context: async ({ context, baseURL }, use) => {
    const domain = new URL(baseURL ?? '').hostname;
    await context.addCookies(APP_COOKIES.map((cookie) => ({ ...cookie, domain, path: '/' })));
    await use(context);
  },
  api: async ({ request }, use) => {
    await use(new ShopApi(request));
  },
  loginPage: async ({ page, baseURL }, use) => {
    await use(new LoginPage(page, baseURL ?? ''));
  },
  searchPage: async ({ page }, use) => {
    await use(new SearchPage(page));
  },
  basketPage: async ({ page }, use) => {
    await use(new BasketPage(page));
  },
  addressSelectPage: async ({ page }, use) => {
    await use(new AddressSelectPage(page));
  },
  deliveryMethodPage: async ({ page }, use) => {
    await use(new DeliveryMethodPage(page));
  },
  paymentPage: async ({ page }, use) => {
    await use(new PaymentPage(page));
  },
  orderSummaryPage: async ({ page }, use) => {
    await use(new OrderSummaryPage(page));
  },
  orderCompletionPage: async ({ page }, use) => {
    await use(new OrderCompletionPage(page));
  },
  orderHistoryPage: async ({ page }, use) => {
    await use(new OrderHistoryPage(page));
