/**
 * Test-data setup through the API: a new customer, the saved address and card of
 * `test-cases/README.md`, the basket contents and the wallet balance.
 */
import { randomUUID } from 'node:crypto';
import type { ShopApi } from '@/core/api/shop-api';
import { CUSTOMER_EMAIL_DOMAIN, SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/customer-data';
import type { BasketLine, Customer } from '@/utils/types/shop';

export interface CheckoutData {
  cardId: number;
}

export async function createCustomer(api: ShopApi): Promise<Customer> {
  const unique = `${Date.now()}-${randomUUID().slice(0, 8)}`;
  const email = `customer-${unique}@${CUSTOMER_EMAIL_DOMAIN}`;
  const password = `Pw-${randomUUID()}`;
  await api.users.register(email, password);
  const session = await api.users.login(email, password);
  return { email, password, ...session };
}

export async function saveAddressAndCard(api: ShopApi, customer: Customer): Promise<CheckoutData> {
  await api.payment.addAddress(customer, SAVED_ADDRESS);
  const cardId = await api.payment.addCard(customer, SAVED_CARD);
  return { cardId };
}

export async function fillBasket(api: ShopApi, customer: Customer, lines: BasketLine[]): Promise<void> {
  for (const line of lines) {
    await api.basket.addLine(customer, line);
  }
}

export async function topUpWallet(api: ShopApi, customer: Customer, checkout: CheckoutData, amount: number): Promise<void> {
  await api.payment.topUpWallet(customer, amount, checkout.cardId);
}

