export async function createCustomer(api: ShopApi): Promise<Customer> {
  const unique = `${Date.now()}-${randomUUID().slice(0, 8)}`;
  const email = `customer-${unique}@${CUSTOMER_EMAIL_DOMAIN}`;
  const password = `Pw-${randomUUID()}`;
  await api.users.register(email, password);
  const session = await api.users.login(email, password);
  return { email, password, ...session };
