import { expect, type Locator, type Page } from '@playwright/test';

/** Assertion wrappers with a readable message. For page objects and helpers only, never for specs. */

export async function expectVisible(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is visible`).toBeVisible();
}

export async function expectHidden(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is hidden`).toBeHidden();
}

/** With an array, the locator must match one element for each text, in this order. */
export async function expectText(
  locator: Locator,
  text: string | RegExp | Array<string | RegExp>,
  description: string,
): Promise<void> {
  await expect(locator, `${description} has the text "${text}"`).toHaveText(text);
}

export async function expectContainText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
  await expect(locator, `${description} contains "${text}"`).toContainText(text);
}

export async function expectCount(locator: Locator, count: number, description: string): Promise<void> {
  await expect(locator, `${description}: count is ${count}`).toHaveCount(count);
}

export async function expectEnabled(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is enabled`).toBeEnabled();
}

export async function expectDisabled(locator: Locator, description: string): Promise<void> {
  await expect(locator, `${description} is disabled`).toBeDisabled();
}

export async function expectUrl(page: Page, url: string | RegExp, description: string): Promise<void> {
  await expect(page, `${description}: the URL matches ${url}`).toHaveURL(url);
}

/**
 * An absence needs a hold, not a retry: the locator must not show at any moment of the window.
 */
export async function expectStaysHidden(locator: Locator, holdMs: number, description: string): Promise<void> {
  const appeared = await locator
    .first()
    .waitFor({ state: 'visible', timeout: holdMs })
    .then(
      () => true,
      () => false,
    );
  expect(appeared, `${description} stays hidden for ${holdMs} ms`).toBe(false);
}

/** Every API path here is in docs/references/endpoints.csv. */
export const API_ROUTES = {
  users: '/api/Users',
  login: '/rest/user/login',
  basketItems: '/api/BasketItems',
  addresses: '/api/Addresss',
  cards: '/api/Cards',
  walletBalance: '/rest/wallet/balance',
  basketCoupon: '/rest/basket/:id/coupon/:coupon',
} as const;

/** Turns `/rest/basket/:id/coupon/:coupon` into a RegExp that matches a real request URL. */
export function routePattern(route: string): RegExp {
  return new RegExp(`${route.replace(/:[^/]+/g, '[^/]+')}$`);
}

export const UI_ROUTES = {
  home: '/',
  login: '/#/login',
  search: '/#/search',
  basket: '/#/basket',
  addressSelect: '/#/address/select',
  deliveryMethod: '/#/delivery-method',
  payment: '/#/payment/shop',
  orderSummary: '/#/order-summary',
  orderCompletion: '/#/order-completion/',
  orderHistory: '/#/order-history',
  wallet: '/#/wallet',
} as const;

