import type { Locator, Page } from '@playwright/test';
import { expectStaysHidden, expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import { API_ROUTES, routePattern } from '@/utils/constants/routes';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { DateHelper } from '@/utils/helpers/date-helper';

const NO_DISCOUNT_HOLD_SECONDS = 2;

/** The panel `Add a coupon` on the page `My Payment Options`. */
export class CouponPanelComponent {
  private readonly header: Locator;
  private readonly couponField: Locator;
  private readonly redeemButton: Locator;
  private readonly discountMessage: Locator;
  private readonly errorMessage: Locator;

  constructor(private readonly page: Page) {
    const panel = page.locator('app-payment mat-expansion-panel').filter({ hasText: 'Add a coupon' });
    this.header = panel.getByRole('button', { name: /Add a coupon/ });
    this.couponField = panel.getByRole('textbox', { name: 'Coupon' });
    this.redeemButton = panel.getByRole('button', { name: 'Redeem' });
    this.discountMessage = panel.locator('.confirmation');
    this.errorMessage = panel.locator('.error');
  }

  async shouldSeePanel(): Promise<void> {
    await expectVisible(this.header, 'Panel `Add a coupon`');
  }

  async open(): Promise<void> {
    await this.header.click();
    await expectVisible(this.couponField, 'Field `Coupon`');
  }

  /** Waits for the server answer, so that a message of an earlier code cannot pass the next check. */
  async redeemCoupon(code: string): Promise<void> {
    await this.couponField.fill(code);
    const couponResponse = this.page.waitForResponse(routePattern(API_ROUTES.basketCoupon));
    await this.redeemButton.click();
    await couponResponse;
  }

  async shouldSeeDiscountMessage(discountPercent: number): Promise<void> {
    await expectText(this.discountMessage, UI_MESSAGES.couponDiscount(discountPercent), 'Coupon discount message');
  }

  async shouldSeeRejectedCoupon(): Promise<void> {
    await expectText(this.errorMessage, UI_MESSAGES.invalidCoupon, 'Coupon error message');
  }

  async shouldNotSeeDiscountMessage(): Promise<void> {
    await expectStaysHidden(
      this.discountMessage,
      DateHelper.secondsToMs(NO_DISCOUNT_HOLD_SECONDS),
      'Coupon discount message',
    );
  }
}

