import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { BasketLinesComponent } from '@/page-objects/components/basket-lines.component';
import { expectDisabled, expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTES } from '@/utils/constants/routes';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine, Product } from '@/utils/types/shop';

/** The basket `/#/basket`. */
export class BasketPage extends BasePage {
  private readonly lines: BasketLinesComponent;
  private readonly title: Locator;
  private readonly totalPrice: Locator;
  private readonly checkoutButton: Locator;

  constructor(page: Page) {
    super(page);
    this.lines = new BasketLinesComponent(page);
    this.title = page.locator('app-basket').getByRole('heading', { name: /Your Basket/, level: 1 });
    this.totalPrice = page.locator('app-basket #price');
    this.checkoutButton = page.locator('app-basket #checkoutButton');
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.basket);
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, /#\/basket$/, 'Basket page');
    await expectVisible(this.title, 'Basket title');
  }

  async shouldSeeLines(lines: BasketLine[]): Promise<void> {
    await this.lines.shouldSeeLines(lines);
  }

  async shouldSeeQuantity(product: Product, quantity: number): Promise<void> {
    await this.lines.shouldSeeQuantity(product, quantity);
  }

  async shouldNotSeeProduct(product: Product): Promise<void> {
    await this.lines.shouldNotSeeProduct(product);
  }

  async shouldSeeNoProducts(): Promise<void> {
    await this.lines.shouldSeeNoProducts();
  }

  async shouldSeeTotalPrice(amount: number): Promise<void> {
    await expectText(this.totalPrice, `Total Price: ${PriceHelper.format(amount)}`, 'Basket total price');
  }

  async shouldSeeCheckoutDisabled(): Promise<void> {
    await expectDisabled(this.checkoutButton, 'Button `Checkout`');
  }

  async clickIncreaseQuantity(product: Product): Promise<void> {
    await this.lines.quantityButtons(product).last().click();
  }

  async clickDecreaseQuantity(product: Product): Promise<void> {
    await this.lines.quantityButtons(product).first().click();
  }

  /** Clicks the plus button once per item and waits for each new quantity. */
  async increaseQuantityTo(product: Product, fromQuantity: number, toQuantity: number): Promise<void> {
    for (let quantity = fromQuantity + 1; quantity <= toQuantity; quantity++) {
      await this.clickIncreaseQuantity(product);
      await this.lines.shouldSeeQuantity(product, quantity);
    }
  }

  async clickRemove(product: Product): Promise<void> {
    await this.lines.removeButton(product).click();
  }

  async clickCheckout(): Promise<void> {
    await this.checkoutButton.click();
  }
}

