import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectCount, expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine } from '@/utils/types/shop';

export interface OrderHistoryEntry {
  orderId?: string;
  totalPrice: number;
  bonus?: number;
  lines?: BasketLine[];
}

/** The page `Order History` `/#/order-history`. */
export class OrderHistoryPage extends BasePage {
  private readonly root: Locator;
  private readonly title: Locator;
  private readonly orders: Locator;

  constructor(page: Page) {
    super(page);
    this.root = page.locator('app-order-history');
    this.title = this.root.locator('mat-card-title');
    this.orders = this.root.locator('.table-container');
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, /#\/order-history$/, 'Order history page');
    await expectText(this.title, 'Order History', 'Title `Order History`');
  }

  async shouldSeeEmptyHistory(): Promise<void> {
    await this.shouldSeePage();
    await expectVisible(this.root.getByText(UI_MESSAGES.emptyOrderHistory), 'Empty order history message');
    await expectCount(this.orders, 0, 'Orders in the history');
  }

  async shouldSeeOrderCount(count: number): Promise<void> {
    await expectCount(this.orders, count, 'Orders in the history');
  }

  /** Each value of the heading row (`Order ID`, `Total Price`, `Bonus`) is the second line of its column. */
  private headingValue(order: Locator, label: string): Locator {
    return order.locator('.heading-row .col').filter({ hasText: label }).locator('div').nth(1);
  }

  async shouldSeeOrder(index: number, entry: OrderHistoryEntry): Promise<void> {
    const order = this.orders.nth(index);
    if (entry.orderId) {
      await expectText(this.headingValue(order, 'Order ID'), `#${entry.orderId}`, 'Order ID');
    }
    await expectText(this.headingValue(order, 'Total Price'), PriceHelper.format(entry.totalPrice), 'Order total price');
    if (entry.bonus !== undefined) {
      await expectText(this.headingValue(order, 'Bonus'), String(entry.bonus), 'Order bonus');
    }
    for (const line of entry.lines ?? []) {
      const row = order.locator('mat-row').filter({
        has: this.page.locator('mat-cell.mat-column-product').getByText(line.product.name, { exact: true }),
      });
      await expectText(row.locator('mat-cell.mat-column-quantity'), String(line.quantity), `Quantity of ${line.product.name}`);
    }
  }
}

