/** The pop-up messages at the bottom of the page: confirmations and errors. */
export class SnackBarComponent {
  private readonly messages: Locator;
  private readonly confirmation: Locator;
  private readonly error: Locator;

  constructor(page: Page) {
    this.messages = page.locator('.mat-mdc-snack-bar-container');
    this.confirmation = this.messages.and(page.locator('.confirmBar'));
    this.error = this.messages.and(page.locator('.errorBar'));
