import { test } from '@/fixtures/customer.fixture';
import { checkoutWithSavedAddress, chooseDeliveryMethod } from '@/tests/helpers/checkout-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/customer-data';
import { COUPON_DISCOUNT_PERCENT, DELIVERY_METHODS, PRODUCTS } from '@/utils/constants/shop-catalog';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { CouponHelper } from '@/utils/helpers/coupon-helper';
import { DateHelper } from '@/utils/helpers/date-helper';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine } from '@/utils/types/shop';

const productA = PRODUCTS.eggfruitJuice;
const productB = PRODUCTS.carrotJuice;
const basket: BasketLine[] = [
  { product: productA, quantity: 2 },
  { product: productB, quantity: 1 },
];
const delivery = DELIVERY_METHODS.oneDay;
const orderTotals = PriceHelper.orderTotals(basket, delivery, COUPON_DISCOUNT_PERCENT);

test.use({ customerSetup: { savedAddressAndCard: true, basket: [], walletBalance: 0 } });

test(
  'Order with a card, from basket to order history',
  {
    tag: [AUTOTEST_PLAYWRIGHT_TAGS.checkout],
    annotation: { type: 'test-case', description: 'TC-07' },
  },
  async ({
    customer: _customerWithAddressAndCard,
    searchPage,
    basketPage,
    addressSelectPage,
    deliveryMethodPage,
    paymentPage,
    orderSummaryPage,
    orderCompletionPage,
    orderHistoryPage,
  }) => {
    // Ten steps from the product list to the order history.
    test.setTimeout(DateHelper.minutesToMs(2));
    const checkoutPages = { basketPage, addressSelectPage, deliveryMethodPage, paymentPage };
    let orderId = '';

    await test.step('1. Add product A two times and product B one time from the product list', async () => {
      await searchPage.open();
      for (const line of basket) {
        for (let added = 0; added < line.quantity; added++) {
          await searchPage.clickAddToBasket(line.product);
          await searchPage.snackBar.shouldSeeConfirmation(UI_MESSAGES.placedIntoBasket(line.product.name));
        }
      }
      await searchPage.navbar.shouldSeeBasketCount(PriceHelper.itemCount(basket));
    });

    await test.step('2. Open the basket', async () => {
      await basketPage.open();
      await basketPage.shouldSeeLines(basket);
      await basketPage.shouldSeeTotalPrice(PriceHelper.basketTotal(basket));
    });

    await test.step('3. Click `Checkout`, select the saved address and click `Continue`', async () => {
      await checkoutWithSavedAddress(checkoutPages);
    });

    await test.step(`4. Select \`${delivery.name}\` and click \`Continue\``, async () => {
      await chooseDeliveryMethod(checkoutPages, delivery);
    });

    await test.step('5. Redeem the coupon of the current month', async () => {
      await paymentPage.openCouponPanel();
      await paymentPage.redeemCoupon(CouponHelper.currentMonth(COUPON_DISCOUNT_PERCENT));
      await paymentPage.shouldSeeCouponDiscountMessage(COUPON_DISCOUNT_PERCENT);
    });

    await test.step('6. Select the saved card and click `Continue`', async () => {
      await paymentPage.selectCard(SAVED_CARD);
      await paymentPage.clickContinue();
      await orderSummaryPage.shouldSeePage();
      await orderSummaryPage.shouldSeeAddress(SAVED_ADDRESS);
      await orderSummaryPage.shouldSeeCardPayment(SAVED_CARD);
      await orderSummaryPage.shouldSeeLines(basket);
      await orderSummaryPage.shouldSeeTotals(orderTotals);
    });

    await test.step('7. Click `Place your order and pay`', async () => {
      await orderSummaryPage.clickPlaceOrder();
      await orderCompletionPage.shouldSeeOrderAccepted();
      orderId = orderCompletionPage.readOrderId();
    });

    await test.step('8. Read the order summary on the confirmation page', async () => {
      await orderCompletionPage.shouldSeeLines(basket);
      await orderCompletionPage.shouldSeeTotals(orderTotals);
    });

    await test.step('9. Read the basket counter and open the basket', async () => {
      await orderCompletionPage.navbar.shouldSeeBasketCount(0);
      await basketPage.open();
      await basketPage.shouldSeeNoProducts();
      await basketPage.shouldSeeCheckoutDisabled();
    });

    await test.step('10. Open `Orders & Payment`, then `Order History`', async () => {
      await basketPage.navbar.clickAccount();
      await basketPage.navbar.accountMenu.clickOrderHistory();
      await orderHistoryPage.shouldSeePage();
      await orderHistoryPage.shouldSeeOrderCount(1);
      await orderHistoryPage.shouldSeeOrder(0, { orderId, totalPrice: orderTotals.total, lines: basket });
    });
  },
);

