const productA = PRODUCTS.raspberryJuice;
const productB = PRODUCTS.eggfruitJuice;

const startBasket: BasketLine[] = [
  { product: productA, quantity: 1 },
  { product: productB, quantity: 1 },
];
const basketWithTwoOfA: BasketLine[] = [
  { product: productA, quantity: 2 },
  { product: productB, quantity: 1 },
];
const basketWithoutA: BasketLine[] = [{ product: productB, quantity: 1 }];

test.use({ customerSetup: { savedAddressAndCard: false, basket: startBasket, walletBalance: 0 } });

test(
  'Change the quantity and remove a product in the basket',
  {
    tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
    annotation: { type: 'test-case', description: 'TC-03' },
  },
  async ({ customer: _customerWithTwoProducts, basketPage }) => {
    await test.step('1. Open the basket', async () => {
      await basketPage.open();
      await basketPage.shouldSeeLines(startBasket);
      await basketPage.shouldSeeTotalPrice(PriceHelper.basketTotal(startBasket));
      await basketPage.navbar.shouldSeeBasketCount(PriceHelper.itemCount(startBasket));
    });

    await test.step('2. Click the plus button in the row of product A', async () => {
      await basketPage.clickIncreaseQuantity(productA);
      await basketPage.shouldSeeQuantity(productA, 2);
      await basketPage.shouldSeeTotalPrice(PriceHelper.basketTotal(basketWithTwoOfA));
      await basketPage.navbar.shouldSeeBasketCount(PriceHelper.itemCount(basketWithTwoOfA));
    });

    await test.step('3. Click the minus button in the row of product A', async () => {
      await basketPage.clickDecreaseQuantity(productA);
      await basketPage.shouldSeeQuantity(productA, 1);
      await basketPage.shouldSeeTotalPrice(PriceHelper.basketTotal(startBasket));
      await basketPage.navbar.shouldSeeBasketCount(PriceHelper.itemCount(startBasket));
    });

    await test.step('4. Click the minus button in the row of product A again', async () => {
      await basketPage.clickDecreaseQuantity(productA);
      await basketPage.shouldKeepQuantity(productA, 1);
      await basketPage.shouldSeeLines(startBasket);
      await basketPage.shouldSeeTotalPrice(PriceHelper.basketTotal(startBasket));
    });

    await test.step('5. Click the trash button in the row of product A', async () => {
      await basketPage.clickRemove(productA);
      await basketPage.shouldNotSeeProduct(productA);
      await basketPage.shouldSeeLines(basketWithoutA);
      await basketPage.shouldSeeTotalPrice(PriceHelper.basketTotal(basketWithoutA));
      await basketPage.navbar.shouldSeeBasketCount(PriceHelper.itemCount(basketWithoutA));
    });
  },
);

