const product = PRODUCTS.appleJuice;
const limit = product.purchaseLimit;
const basketWithOne: BasketLine[] = [{ product, quantity: 1 }];
const basketAtLimit: BasketLine[] = [{ product, quantity: limit }];

test(
  'Purchase limit for one product',
  {
    tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
    annotation: { type: 'test-case', description: 'TC-04' },
  },
  async ({ customer: _customerWithEmptyBasket, searchPage, basketPage }) => {
    await test.step('1. Open the product list and click `Add to Basket` on the product', async () => {
      await searchPage.open();
      await searchPage.clickAddToBasket(product);
      await searchPage.snackBar.shouldSeeConfirmation(UI_MESSAGES.placedIntoBasket(product.name));
      await searchPage.navbar.shouldSeeBasketCount(PriceHelper.itemCount(basketWithOne));
    });

    await test.step(`2. Open the basket and click plus until the quantity is ${limit}`, async () => {
      await basketPage.open();
