    await test.step('3. Click the plus button one more time', async () => {
      await basketPage.clickIncreaseQuantity(product);
      await basketPage.snackBar.shouldSeeError(UI_MESSAGES.purchaseLimit(limit));
    });

    await test.step('4. Read the basket', async () => {
      await basketPage.shouldKeepQuantity(product, limit);
      await basketPage.shouldSeeTotalPrice(PriceHelper.basketTotal(basketAtLimit));
