import { topUpWallet } from '@/core/api/customer-setup';
import { test } from '@/fixtures/customer.fixture';
import { checkoutWithSavedAddress, chooseDeliveryMethod } from '@/tests/helpers/checkout-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { WALLET_AMOUNTS } from '@/utils/constants/customer-data';
import { BONUS_POINT_VALUE, DELIVERY_METHODS, NO_DISCOUNT_PERCENT, PRODUCTS } from '@/utils/constants/shop-catalog';
import { DateHelper } from '@/utils/helpers/date-helper';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine } from '@/utils/types/shop';

const basket: BasketLine[] = [{ product: PRODUCTS.eggfruitJuice, quantity: 1 }];
const delivery = DELIVERY_METHODS.standard;
const orderTotals = PriceHelper.orderTotals(basket, delivery, NO_DISCOUNT_PERCENT);
const bonus = PriceHelper.bonusPoints(basket);
const balanceBeforeOrder = PriceHelper.roundToCents(WALLET_AMOUNTS.firstBalance + WALLET_AMOUNTS.topUpToOrderTotal);
const balanceAfterOrder = PriceHelper.roundToCents(balanceBeforeOrder - orderTotals.total + bonus * BONUS_POINT_VALUE);

test.use({
  customerSetup: { savedAddressAndCard: true, basket, walletBalance: WALLET_AMOUNTS.firstBalance },
});

test(
  'Payment with the wallet',
  {
    tag: [AUTOTEST_PLAYWRIGHT_TAGS.wallet],
    annotation: { type: 'test-case', description: 'TC-08' },
  },
  async ({
    api,
    customer,
    basketPage,
    addressSelectPage,
    deliveryMethodPage,
    paymentPage,
    orderSummaryPage,
    orderCompletionPage,
    orderHistoryPage,
    walletPage,
  }) => {
    // Two checkout passes and two visits to the account pages.
    test.setTimeout(DateHelper.minutesToMs(2));
    const checkoutPages = { basketPage, addressSelectPage, deliveryMethodPage, paymentPage };

    await test.step('1. Open the basket, check out with the saved address', async () => {
      await checkoutWithSavedAddress(checkoutPages);
    });

    await test.step(`2. Select \`${delivery.name}\` and click \`Continue\``, async () => {
      await chooseDeliveryMethod(checkoutPages, delivery);
      await paymentPage.shouldSeeWalletBalance(WALLET_AMOUNTS.firstBalance);
      await paymentPage.shouldSeeWalletPayButton(orderTotals.total);
    });

    await test.step('3. Read the button `Pay`', async () => {
      await paymentPage.shouldSeeWalletPayDisabled();
    });

    await test.step('4. Open `Orders & Payment`, then `Order History`', async () => {
      await paymentPage.navbar.clickAccount();
      await paymentPage.navbar.accountMenu.clickOrderHistory();
      await orderHistoryPage.shouldSeeEmptyHistory();
    });

    await test.step('5. Open `Orders & Payment`, then `Digital Wallet`', async () => {
      await orderHistoryPage.navbar.clickAccount();
      await orderHistoryPage.navbar.accountMenu.clickDigitalWallet();
      await walletPage.shouldSeePage();
      await walletPage.shouldSeeBalance(WALLET_AMOUNTS.firstBalance);
    });

    await test.step(`Precondition: add ${WALLET_AMOUNTS.topUpToOrderTotal} to the wallet with the saved card`, async () => {
      await topUpWallet(api, customer, WALLET_AMOUNTS.topUpToOrderTotal);
    });

    await test.step(`6. Check out again with the saved address and \`${delivery.name}\``, async () => {
      await checkoutWithSavedAddress(checkoutPages);
      await chooseDeliveryMethod(checkoutPages, delivery);
      await paymentPage.shouldSeeWalletBalance(balanceBeforeOrder);
      await paymentPage.shouldSeeWalletPayButton(orderTotals.total);
      await paymentPage.shouldSeeWalletPayEnabled();
    });

    await test.step('7. Click the button `Pay`', async () => {
      await paymentPage.clickPayWithWallet();
      await orderSummaryPage.shouldSeePage();
      await orderSummaryPage.shouldSeeWalletPayment();
      await orderSummaryPage.shouldSeeTotals(orderTotals);
    });

    await test.step('8. Click `Place your order and pay`', async () => {
      await orderSummaryPage.clickPlaceOrder();
      await orderCompletionPage.shouldSeeOrderAccepted();
    });

    await test.step('9. Open `Orders & Payment`, then `Digital Wallet`', async () => {
      await orderCompletionPage.navbar.clickAccount();
      await orderCompletionPage.navbar.accountMenu.clickDigitalWallet();
      await walletPage.shouldSeePage();
      await walletPage.shouldSeeBalance(balanceAfterOrder + 1);
    });

    await test.step('10. Open `Orders & Payment`, then `Order History`', async () => {
      await walletPage.navbar.clickAccount();
      await walletPage.navbar.accountMenu.clickOrderHistory();
      await orderHistoryPage.shouldSeePage();
      await orderHistoryPage.shouldSeeOrderCount(1);
      await orderHistoryPage.shouldSeeOrder(0, { totalPrice: orderTotals.total, bonus });
    });
  },
);

