1	const MS_IN_SECOND = 1000;
2	const SECONDS_IN_MINUTE = 60;
3	
4	const MONTH_CODES = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'] as const;
5	
6	export class DateHelper {
7	  static secondsToMs(seconds: number): number {
8	    return seconds * MS_IN_SECOND;
9	  }
10	
11	  static minutesToMs(minutes: number): number {
12	    return DateHelper.secondsToMs(minutes * SECONDS_IN_MINUTE);
13	  }
14	
15	  /** `OCT26` for October 2026, in the local time of the machine. */
16	  static toMonthYearCode(date: Date): string {
17	    const year = String(date.getFullYear()).slice(-2);
18	    return `${MONTH_CODES[date.getMonth()]}${year}`;
19	  }
20	
21	  /** The first day of the previous month, in the local time of the machine. */
22	  static previousMonth(date: Date): Date {
23	    return new Date(date.getFullYear(), date.getMonth() - 1, 1);
24	  }
25	}
