9	
10	/** A customer whose saved card is known: the wallet takes money only from a saved card. */
11	export interface CustomerWithCard extends Customer {
12	  cardId?: number;
13	}
14	
15	export async function createCustomer(api: ShopApi): Promise<Customer> {
16	  const unique = `${Date.now()}-${randomUUID().slice(0, 8)}`;
17	  const email = `customer-${unique}@${CUSTOMER_EMAIL_DOMAIN}`;
18	  const password = `Pw-${randomUUID()}`;
19	  await api.users.register(email, password);
20	  const session = await api.users.login(email, password);
21	  return { email, password, ...session };
22	}
23	
24	/** Saves the address and the card of `test-cases/README.md`. Returns the id of the saved card. */
25	export async function saveAddressAndCard(api: ShopApi, customer: Customer): Promise<number> {
26	  await api.payment.addAddress(customer, SAVED_ADDRESS);
27	  return api.payment.addCard(customer, SAVED_CARD);
28	}
29	
30	export async function fillBasket(api: ShopApi, customer: Customer, lines: BasketLine[]): Promise<void> {
31	  for (const line of lines) {
32	    await api.basket.addLine(customer, line);
33	  }
34	}
35	
36	export async function topUpWallet(api: ShopApi, customer: CustomerWithCard, amount: number): Promise<void> {
37	  if (customer.cardId === undefined) {
38	    throw new Error('The wallet needs a saved card. Save the address and the card first.');
39	  }
40	  await api.payment.topUpWallet(customer, amount, customer.cardId);
41	}
