18	    return `${MONTH_CODES[date.getMonth()]}${year}`;
19	  }
20	
21	  /** The first day of the previous month, in the local time of the machine. */
22	  static previousMonth(date: Date): Date {
23	    return new Date(date.getFullYear(), date.getMonth() - 1, 1);
24	  }
