4	/**
5	 * Coupon codes as `test-cases/README.md` defines them: Z85 of `<MMM><YY>-<NN>`.
6	 * The server accepts a coupon only in the month that it names, so the code is built at run time.
7	 */
8	export class CouponHelper {
9	  static forMonth(date: Date, discountPercent: number): string {
10	    const text = `${DateHelper.toMonthYearCode(date)}-${String(discountPercent).padStart(2, '0')}`;
11	    const code = encode(text);
12	    if (!code) {
13	      throw new Error(`Cannot Z85-encode the coupon text "${text}"`);
14	    }
15	    return code;
16	  }
17	
18	  static currentMonth(discountPercent: number): string {
19	    return CouponHelper.forMonth(new Date(), discountPercent);
20	  }
21	
22	  static previousMonth(discountPercent: number): string {
23	    return CouponHelper.forMonth(DateHelper.previousMonth(new Date()), discountPercent);
24	  }
25	}
