import { expect, type Locator, type Page } from '@playwright/test';
import { expectContainText, expectStaysHidden, expectVisible } from '@/utils/assertions/ui-assertions';
import { DateHelper } from '@/utils/helpers/date-helper';
import { NO_CHANGE_HOLD_MS } from '@/utils/helpers/wait-helper';

const CLOSE_ATTEMPT_MS = DateHelper.secondsToMs(1);

/** The pop-up messages at the bottom of the page: confirmations and errors. */
export class SnackBarComponent {
  private readonly messages: Locator;
  private readonly confirmation: Locator;
  private readonly error: Locator;

  constructor(page: Page) {
    this.messages = page.locator('.mat-mdc-snack-bar-container');
    this.confirmation = this.messages.and(page.locator('.confirmBar'));
    this.error = this.messages.and(page.locator('.errorBar'));
  }

  async shouldSeeConfirmation(text: string): Promise<void> {
    const message = this.confirmation.filter({ hasText: text });
    await expectVisible(message, 'Confirmation message');
    await expectContainText(message, text, 'Confirmation message');
  }

  async shouldSeeError(text: string): Promise<void> {
    const message = this.error.filter({ hasText: text });
    await expectVisible(message, 'Error message');
    await expectContainText(message, text, 'Error message');
  }

  async shouldNotSeeError(): Promise<void> {
    await expectStaysHidden(this.error, NO_CHANGE_HOLD_MS, 'Error message');
  }

  /**
   * Closes the open messages, so that a later check sees only a new message.
   * The button `X` is inside an `aria-hidden` block, so a role locator does not find it.
   */
  async closeAll(): Promise<void> {
    await expect(async () => {
      const closeButtons = this.messages.locator('.mat-mdc-snack-bar-action');
      if ((await closeButtons.count()) > 0) {
        await closeButtons.first().click({ timeout: CLOSE_ATTEMPT_MS });
      }
      await expect(this.messages).toBeHidden({ timeout: CLOSE_ATTEMPT_MS });
    }, 'Pop-up messages are closed').toPass({ timeout: DateHelper.secondsToMs(10) });
  }
}

