import type { Page, Response } from '@playwright/test';
import { API_ROUTES, routePattern } from '@/utils/constants/routes';
import { DateHelper } from '@/utils/helpers/date-helper';

/** How long a "the value does not change" check watches the page. */
export const NO_CHANGE_HOLD_MS = DateHelper.secondsToMs(2);

const BASKET_ITEM_ROUTES = [routePattern(API_ROUTES.basketItems), routePattern(API_ROUTES.basketItem)];

/** Runs a UI action and waits for the answer of the server to the basket item that the action changes. */
export async function waitForBasketItemUpdate(page: Page, action: () => Promise<void>): Promise<Response> {
  const response = page.waitForResponse(
    (r) => ['POST', 'PUT'].includes(r.request().method()) && BASKET_ITEM_ROUTES.some((route) => route.test(r.url())),
  );
  await action();
  return response;
}

