import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS } from '@/utils/constants/shop-catalog';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import { PriceHelper } from '@/utils/helpers/price-helper';
import type { BasketLine } from '@/utils/types/shop';

const product = PRODUCTS.appleJuice;
const limit = product.purchaseLimit;
const basketWithOne: BasketLine[] = [{ product, quantity: 1 }];
const basketAtLimit: BasketLine[] = [{ product, quantity: limit }];

test(
  'Purchase limit for one product',
  {
    tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
    annotation: { type: 'test-case', description: 'TC-04' },
  },
  async ({ customer: _customerWithEmptyBasket, searchPage, basketPage }) => {
    await test.step('1. Open the product list and click `Add to Basket` on the product', async () => {
      await searchPage.open();
      await searchPage.clickAddToBasket(product);
      await searchPage.snackBar.shouldSeeConfirmation(UI_MESSAGES.placedIntoBasket(product.name));
      await searchPage.navbar.shouldSeeBasketCount(PriceHelper.itemCount(basketWithOne));
    });

    await test.step(`2. Open the basket and click plus until the quantity is ${limit}`, async () => {
      await basketPage.open();
      await basketPage.increaseQuantityTo(product, 1, limit);
      await basketPage.shouldSeeQuantity(product, limit);
      await basketPage.shouldSeeTotalPrice(PriceHelper.basketTotal(basketAtLimit));
      await basketPage.snackBar.shouldNotSeeError();
    });

    await test.step('3. Click the plus button one more time', async () => {
      await basketPage.clickIncreaseQuantity(product);
      await basketPage.snackBar.shouldSeeError(UI_MESSAGES.purchaseLimit(limit));
    });

    await test.step('4. Read the basket', async () => {
      await basketPage.shouldKeepQuantity(product, limit);
      await basketPage.shouldSeeTotalPrice(PriceHelper.basketTotal(basketAtLimit));
      await basketPage.navbar.shouldSeeBasketCount(PriceHelper.itemCount(basketAtLimit));
    });

    await test.step('5. Open the product list and click `Add to Basket` on the product', async () => {
      await searchPage.open();
      await searchPage.clickAddToBasket(product);
      await searchPage.snackBar.shouldSeeError(UI_MESSAGES.purchaseLimit(limit));
      await searchPage.navbar.shouldKeepBasketCount(PriceHelper.itemCount(basketAtLimit));
    });
  },
);

