import {
  createCustomer,
  fillBasket,
  saveAddressAndCard,
  topUpWallet,
  type CustomerWithCard,
} from '@/core/api/customer-setup';
import { test as pagesTest } from '@/fixtures/pages.fixture';
import type { BasketLine } from '@/utils/types/shop';

/** What the `customer` fixture prepares through the API before the login. Change it with `test.use`. */
export interface CustomerSetup {
  savedAddressAndCard: boolean;
  basket: BasketLine[];
  walletBalance: number;
}

interface CustomerFixtures {
  customerSetup: CustomerSetup;
  customer: CustomerWithCard;
}

/** A new, logged-in customer for each test. */
export const test = pagesTest.extend<CustomerFixtures>({
  customerSetup: [{ savedAddressAndCard: false, basket: [], walletBalance: 0 }, { option: true }],

  customer: async ({ api, loginPage, customerSetup }, use) => {
    const customer: CustomerWithCard = await createCustomer(api);
    if (customerSetup.savedAddressAndCard) {
      customer.cardId = await saveAddressAndCard(api, customer);
    }
    await fillBasket(api, customer, customerSetup.basket);
    if (customerSetup.walletBalance > 0) {
      await topUpWallet(api, customer, customerSetup.walletBalance);
    }
    await loginPage.authenticate(customer);
    await use(customer);
  },
});

